ON CONFLICT (moe_institution_code) DO UPDATE SET
 name = EXCLUDED.name, province = EXCLUDED.province, education_level = EXCLUDED.education_level,
 category = EXCLUDED.category, source = EXCLUDED.source, source_version = EXCLUDED.source_version, updated_at = now();

SELECT id, 'smail.nju.edu.cn', 'student', true, true FROM institutions WHERE moe_institution_code = '4132010284'
ON CONFLICT (domain) DO UPDATE SET institution_id = EXCLUDED.institution_id, credential_type = EXCLUDED.credential_type, auto_verify = EXCLUDED.auto_verify, active = EXCLUDED.active, updated_at = now();

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM team_application_members m
    INNER JOIN team_applications a ON a.id = m.application_id
    WHERE a.status IN ('draft', 'submitted', 'waitlisted')
    GROUP BY a.season_id, m.user_id HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Cannot establish active team application claims: existing active membership conflict';
  END IF;
END $$;

SELECT a.season_id, m.user_id, m.application_id
FROM team_application_members m
INNER JOIN team_applications a ON a.id = m.application_id
WHERE a.status IN ('draft', 'submitted', 'waitlisted');

